// Central copy for ChessPulse. Plain language, one term per concept.
// Internal labels (Layer, phase numbers) must not appear here or in components.
export const COPY = {
  insight: {
    label: 'Reading (optional)',
    title: 'Reading',
    inferredLabel: 'INFERRED — written by a model from the numbers above. Not measured.',
  },
} as const;
---styles head---
@import './tokens.css';

:root {
  color: var(--text);
  background: var(--bg);
  font-family: var(--font-ui);
  font-variant-numeric: tabular-nums;
}


body {
  margin: 0;
}

main {
  min-height: 100vh;
  box-sizing: border-box;
  max-width: 960px;
  padding: 48px;
}

.label {
  margin: 0 0 12px;
  color: var(--muted);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: 12px;
}

h1 {
  margin: 0 0 12px;
  font-size: 32px;
  font-weight: 560;
}

p {
  margin: 0;
  color: var(--muted);
  max-width: 36rem;
  line-height: 1.5;
}

button {
  margin: 0;
  padding: 8px 16px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: var(--surface);
  color: var(--text);
  font: inherit;
  font-size: 16px;
}

button[aria-pressed='true'] {
  border-color: var(--text);
}

button:disabled {
  color: var(--muted);
}

button:focus-visible,
textarea:focus-visible,
select:focus-visible,
.strip:focus-visible,
.timeline-frame:focus-visible {
  outline: 2px solid var(--text);
  outline-offset: 2px;
}

.primary-btn {
