import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { createElement } from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { SensingControls, type SensingControlsProps } from './SensingControls.js';

function render(overrides: Partial<SensingControlsProps> = {}): string {
  const props: SensingControlsProps = {
    elapsedLabel: '12:34',
    limitWarning: null,
    qualityLabel: 'Good signal',
    betweenGames: false,
    markedGames: 0,
    gapPending: false,
    confirmingStop: false,
    onGap: () => undefined,
    onRequestStop: () => undefined,
    onConfirmStop: () => undefined,
    onKeepSensing: () => undefined,
    ...overrides,
  };
  return renderToStaticMarkup(createElement(SensingControls, props));
}

describe('SensingControls markup', () => {
  it('shows the clock, quality, playing state, and marked-game count', () => {
    const html = render();
    assert.match(html, />12:34</);
    assert.match(html, /elapsed/);
    assert.match(html, /Good signal/);
    assert.match(html, /Playing/);
    assert.match(html, /0 games marked/);
    assert.match(html, />Game ended</);
  });

  it('shows the waiting state with the next-game action and the count', () => {
    const html = render({ betweenGames: true, markedGames: 3 });
    assert.match(html, /Game ended — waiting for the next game/);
    assert.match(html, /3 games marked/);
    assert.match(html, />Next game started</);
  });

  it('shows the 80-minute warning when present', () => {
    const html = render({
      limitWarning: '10 minutes left before the 90-minute limit.',
    });
    assert.match(html, /10 minutes left before the 90-minute limit\./);
  });

  it('asks for confirmation before stopping and offers Keep sensing', () => {
    const html = render({ confirmingStop: true });
    assert.match(html, /Stop this session\?/);
    assert.match(html, /You can(?:&apos;|&#x27;)t add to it later\./);
    assert.match(html, />Stop</);
    assert.match(html, /Keep sensing/);
    assert.equal(html.includes('Game ended'), false);
  });

  it('disables the gap button while a gap change is pending', () => {
    const html = render({ gapPending: true });
    assert.match(html, /<button[^>]*disabled[^>]*>Game ended<\/button>/);
  });
});

// What: the stored-session rows shared by Home and the Sessions screen.
// Why: opening, exporting, and deleting must be one set of controls, with the same labels and guards.
// Removed: history would be a dead list, and delete/export would have no confirmation.
import { useEffect, useId, useRef, useState } from 'react';
import type { SessionSummary } from '../shared/contracts.js';
import {
  coverageLabel,
  formatSessionDate,
  formatSessionDuration,
  reportPresenceLabel,
} from '../shared/session-list.js';

export interface SessionListProps {
  sessions: SessionSummary[];
  emptyMessage: string;
  unreadable?: number;
  onOpen(sessionId: string): void;
  onDelete(sessionId: string): void;
  onExport(sessionId: string): void;
  heading?: string;
}

export function SessionList({
  sessions,
  emptyMessage,
  unreadable = 0,
  onOpen,
  onDelete,
  onExport,
  heading = 'Saved sessions',
}: SessionListProps) {
  const [confirmation, setConfirmation] = useState<{
    id: string;
    kind: 'delete' | 'export';
  } | null>(null);

  if (sessions.length === 0 && unreadable === 0) {
    return <p className="session-empty">{emptyMessage}</p>;
  }

  return (
    <section className="session-list-section" aria-label={heading}>
      {unreadable > 0 ? (
        <p className="session-unreadable" role="status">
          {unreadable} saved {unreadable === 1 ? 'session' : 'sessions'} could not be read.
        </p>
      ) : null}
      <ol className="session-list">
        {sessions.map((session) => (
          <SessionRow
            key={session.id}
            session={session}
            confirmation={confirmation?.id === session.id ? confirmation.kind : null}
            onOpen={() => onOpen(session.id)}
            onDelete={() => {
              setConfirmation(null);
              onDelete(session.id);
            }}
            onExport={() => {
              setConfirmation(null);
              onExport(session.id);
            }}
            onRequestDelete={() => setConfirmation({ id: session.id, kind: 'delete' })}
            onRequestExport={() => setConfirmation({ id: session.id, kind: 'export' })}
            onCancel={() => setConfirmation(null)}
          />
        ))}
      </ol>
    </section>
  );
}

function SessionRow({
  session,
  confirmation,
  onOpen,
  onDelete,
  onExport,
  onRequestDelete,
  onRequestExport,
  onCancel,
}: {
  session: SessionSummary;
  confirmation: 'delete' | 'export' | null;
  onOpen(): void;
  onDelete(): void;
  onExport(): void;
  onRequestDelete(): void;
  onRequestExport(): void;
  onCancel(): void;
}) {
  const titleId = useId();
  const cancelRef = useRef<HTMLButtonElement | null>(null);
  const deleteRef = useRef<HTMLButtonElement | null>(null);
  const exportRef = useRef<HTMLButtonElement | null>(null);
  const previousConfirmation = useRef<'delete' | 'export' | null>(null);
  const date = new Date(session.startedAtEpochMs);
  const dateTime = Number.isNaN(date.getTime()) ? undefined : date.toISOString();

  useEffect(() => {
    if (confirmation) {
      previousConfirmation.current = confirmation;
      cancelRef.current?.focus();
    } else if (previousConfirmation.current) {
      const target =
        previousConfirmation.current === 'delete' ? deleteRef.current : exportRef.current;
      previousConfirmation.current = null;
      target?.focus();
    }
  }, [confirmation]);

  return (
    <li className="session-row">
      <div className="session-row-main">
        <time className="session-date" dateTime={dateTime}>
          {formatSessionDate(session.startedAtEpochMs)}
        </time>
        <span className="session-detail">{formatSessionDuration(session.durationMs)}</span>
        <span className="session-detail">{coverageLabel(session.coveragePct)}</span>
        <span className={session.hasReport ? 'session-report' : 'session-report muted'}>
          {reportPresenceLabel(session.hasReport)}
        </span>
      </div>

      {confirmation ? (
        <div className="session-confirm" role="group" aria-labelledby={titleId}>
          <p id={titleId}>
            {confirmation === 'delete'
              ? 'Delete this session? This cannot be undone.'
              : 'Export this report? The file contains no pulse samples.'}
          </p>
          <div className="actions">
            <button
              type="button"
              className="primary-btn"
              onClick={confirmation === 'delete' ? onDelete : onExport}
            >
              {confirmation === 'delete' ? 'Delete' : 'Export'}
            </button>
            <button type="button" ref={cancelRef} onClick={onCancel}>
              Cancel
            </button>
          </div>
        </div>
      ) : (
        <div className="session-actions">
          <button type="button" onClick={onOpen}>
            Open
          </button>
          <button type="button" ref={exportRef} disabled={!session.hasReport} onClick={onRequestExport}>
            Export
          </button>
          <button type="button" ref={deleteRef} onClick={onRequestDelete}>
            Delete
          </button>
          {!session.hasReport ? (
            <span className="session-detail">Export is available after a report is built.</span>
          ) : null}
        </div>
      )}
