// What: a small DOM harness for renderer interaction tests.
// Why: the markup tests use `react-dom/server`, which cannot click, focus, or observe effects.
//      S57 adds jsdom so focus-return and keyboard behaviour can be asserted instead of reviewed.
// Removed: the focus claims in S49/S50 and H-27 would stay code-reviewed only.
import { JSDOM } from 'jsdom';
import { act, type ReactElement } from 'react';
import { createRoot } from 'react-dom/client';

export interface DomHarness {
  readonly document: Document;
  readonly window: Window;
  readonly container: HTMLElement;
  render(element: ReactElement): void;
  click(element: Element): void;
  keyDown(element: Element, key: string): void;
  unmount(): void;
}

export function mountDom(element: ReactElement): DomHarness {
  const dom = new JSDOM('<!doctype html><html><body></body></html>', {
    pretendToBeVisual: true,
  });
  const scope = globalThis as unknown as Record<string, unknown>;
  scope.IS_REACT_ACT_ENVIRONMENT = true;
  scope.window = dom.window;
  scope.document = dom.window.document;
  scope.HTMLElement = dom.window.HTMLElement;
  scope.Node = dom.window.Node;
  scope.Event = dom.window.Event;
  scope.KeyboardEvent = dom.window.KeyboardEvent;
  scope.MouseEvent = dom.window.MouseEvent;

  const container = dom.window.document.createElement('div');
  dom.window.document.body.append(container);
  const root = createRoot(container);

  function render(next: ReactElement): void {
    act(() => {
      root.render(next);
    });
  }

  render(element);

  return {
    document: dom.window.document,
    window: dom.window,
    container,
    render,
    click(target: Element): void {
      act(() => {
        (target as HTMLElement).click();
      });
    },
    keyDown(target: Element, key: string): void {
      act(() => {
        target.dispatchEvent(new dom.window.KeyboardEvent('keydown', { key, bubbles: true }));
      });
    },
    unmount(): void {
      act(() => {
        root.unmount();
      });
      dom.window.close();
    },
  };
}

export function findButton(document: Document, label: string): HTMLButtonElement {
  const match = [...document.querySelectorAll('button')].find(
    (button) => button.textContent?.trim() === label,
  );
  if (!(match instanceof document.defaultView!.HTMLButtonElement)) {
    throw new Error(`No button labelled "${label}".`);
  }
  return match;
}

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { createElement } from 'react';
import { findButton, mountDom } from './dom-harness.js';
import { SensingControls, type SensingControlsProps } from './SensingControls.js';

function props(overrides: Partial<SensingControlsProps> = {}): SensingControlsProps {
  return {
    elapsedLabel: '12:34',
    limitWarning: null,
    qualityLabel: 'Good signal',
    betweenGames: false,
    markedGames: 0,
    gapPending: false,
    confirmingStop: false,
    onGap: () => undefined,
    onRequestStop: () => undefined,
    onConfirmStop: () => undefined,
    onKeepSensing: () => undefined,
    ...overrides,
  };
}

describe('SensingControls interaction', () => {
  it('moves focus to Keep sensing when the confirmation opens', () => {
    const harness = mountDom(
      createElement(SensingControls, props({ confirmingStop: true })),
    );
    assert.equal(harness.document.activeElement?.textContent, 'Keep sensing');
    harness.unmount();
  });

  it('keeps sensing on Escape without confirming', () => {
    let kept = 0;
    let stopped = 0;
    const harness = mountDom(
      createElement(
        SensingControls,
        props({
          confirmingStop: true,
          onKeepSensing: () => {
            kept += 1;
          },
          onConfirmStop: () => {
            stopped += 1;
          },
        }),
      ),
    );
    const group = harness.document.querySelector('.stop-confirm');
    assert.ok(group);
    harness.keyDown(group, 'Escape');
    assert.equal(kept, 1);
    assert.equal(stopped, 0);
    harness.unmount();
  });

  it('returns focus to Stop sensing when the confirmation closes', () => {
    const harness = mountDom(
      createElement(SensingControls, props({ confirmingStop: true })),
    );
    harness.render(createElement(SensingControls, props({ confirmingStop: false })));
    assert.equal(harness.document.activeElement?.textContent, 'Stop sensing');
    harness.unmount();
  });

  it('requests a stop from the Stop sensing button', () => {
    let requested = 0;
    const harness = mountDom(
      createElement(
        SensingControls,
        props({
          onRequestStop: () => {
            requested += 1;
          },
        }),
      ),
    );
    harness.click(findButton(harness.document, 'Stop sensing'));
    assert.equal(requested, 1);
    harness.unmount();
  });
});

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { createElement } from 'react';
import type { SessionSummary } from '../shared/contracts.js';
import { findButton, mountDom } from './dom-harness.js';
import { SessionList } from './SessionList.js';

const sessions: SessionSummary[] = [
  {
    id: 'session-one',
    startedAtEpochMs: 1_700_000_000_000,
    durationMs: 65_000,
    coveragePct: 75.4,
    hasReport: true,
  },
  {
    id: 'session-two',
    startedAtEpochMs: 1_700_003_600_000,
    durationMs: 1_000,
    coveragePct: 20,
    hasReport: false,
  },
];

function list(overrides: {
  onDelete?: (id: string) => void;
  onExport?: (id: string) => void;
  onOpen?: (id: string) => void;
} = {}) {
  return createElement(SessionList, {
    sessions,
    emptyMessage: 'No sessions yet.',
    onOpen: overrides.onOpen ?? (() => undefined),
    onDelete: overrides.onDelete ?? (() => undefined),
    onExport: overrides.onExport ?? (() => undefined),
  });
}

describe('SessionList interaction', () => {
  it('asks for confirmation and focuses Cancel before deleting', () => {
    let deleted = '';
    const harness = mountDom(list({ onDelete: (id) => { deleted = id; } }));
    harness.click(findButton(harness.document, 'Delete'));
    assert.match(harness.document.body.textContent ?? '', /Delete this session\?/);
    assert.equal(harness.document.activeElement?.textContent, 'Cancel');
    assert.equal(deleted, '');
    harness.click(findButton(harness.document, 'Cancel'));
    assert.equal(deleted, '');
    harness.unmount();
  });

  it('returns focus to the initiating Delete button when cancelled', () => {
    const harness = mountDom(list());
    const deleteButton = findButton(harness.document, 'Delete');
    harness.click(deleteButton);
    harness.click(findButton(harness.document, 'Cancel'));
    assert.equal(harness.document.activeElement?.textContent, 'Delete');
    harness.unmount();
  });

  it('deletes once confirmed', () => {
    let deleted = '';
    const harness = mountDom(list({ onDelete: (id) => { deleted = id; } }));
    harness.click(findButton(harness.document, 'Delete'));
    harness.click(findButton(harness.document, 'Delete'));
    assert.equal(deleted, 'session-one');
    harness.unmount();
  });

  it('does not open export for a session without a report', () => {
    const harness = mountDom(list());
    const exportButtons = [...harness.document.querySelectorAll('button')].filter(
      (button) => button.textContent?.trim() === 'Export',
    );
    assert.equal(exportButtons.length, 2);
    harness.click(exportButtons[1]);
    assert.equal(harness.document.querySelector('.session-confirm'), null);
    harness.unmount();
  });
});

